import{z as l,x as s,o as r,c as d,q as o,j as t,D as a,d as E,s as i,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"拍卖的结构估计深入","description":"","frontmatter":{"title":"拍卖的结构估计深入","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-auction-deep.md","filePath":"econ/se-auction-deep.md","lastUpdated":1791413859000}'),p={name:"econ/se-auction-deep.md"};function c(C,e,u,m,h,D){const B=s("Mermaid");return r(),d("div",null,[e[2]||(e[2]=o('<h1 id="拍卖的结构估计深入" tabindex="-1">拍卖的结构估计深入 <a class="header-anchor" href="#拍卖的结构估计深入" aria-label="Permalink to &quot;拍卖的结构估计深入&quot;">​</a></h1><div class="epigraph"><p>一阶条件只在私人价值、风险中性、人数外生时把出价反演成估值；三个前提动一个，反演公式就得跟着动，否则估出来的是策略的影子，不是需求的来源。</p><footer>—— 据 Guerre, Perrigne and Vuong, Econometrica 2000；Haile and Tamer, JPE 2003 整理</footer></div><p><a href="/econ/se-production-deep">上一课</a>把技术边的反演推到动态矩与加成。本课回到博弈场。<a href="/econ/auction-structural-estimation">主干的拍卖课</a>在一阶条件 \\(v=b+G(b)/[(n-1)g(b)]\\) 上把 IPV 第一价格估完，但那道反演有四个旋钮：风险态度、不可观测异质、参与内生、信息结构。本课逐个拧。储备价与采购招标的反事实在最后一步重解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四个缺口各有出处。风险厌恶：出价抬高可以来自估值高，也可以来自怕输——反演公式少一个效用曲率参数，估值分布 \\(F\\) 与风险态度纠缠。异质性：标的地基、许可范围这些拍卖层面观测不到的变量进估值，边缘密度 \\(g\\) 是混合，直接核估把异质当成了策略。参与：\\(n\\) 对储备价与预期利润有反应，把 \\(n\\) 当外生，反事实储备价系统性错。信息结构：<a href="/econ/winner-curse">共同价值</a>下出价还要过滤「赢得意味着别人也觉得值」，IPV 公式把诅咒写进了估值。</p><p><span class="marginnote">术语翻译：「反演」就是倒着用均衡公式：理论说「估值越高出价越狠」，于是观测到出价分布后往回推估值分布。前提是公式里的其他量（人数、风险态度、信息结构）都已知；少一个已知量，倒推就是欠定的，估出来的东西没有唯一定义。</span></p><h3 id="逐个修的反演" tabindex="-1">逐个修的反演 <a class="header-anchor" href="#逐个修的反演" aria-label="Permalink to &quot;逐个修的反演&quot;">​</a></h3><p>风险厌恶：一阶条件多出 \\(u&#39;\\) 的比率，Guerre–Perrigne–Vuong 2009 用不同 \\(n\\) 的场次把它与 \\(F\\) 分开——人数变，策略变的方式识别曲率。异质：若 \\(v=u\\cdot e\\)（共同乘数加独立噪声），观测密度是卷积，用反卷积把共同成分拆出来。参与：进入成本进估值，\\(n\\) 的分布对政策变量的反应变成矩的一部分。共同价值与不对称：识别弱得多，Athey–Haile 2002 列出哪些结构在哪些数据下可识别、哪些只能定界。</p><p><span class="marginnote">Haile–Tamer 2003 的出路是部分识别：不假设英式拍卖行为精确最优，只假设出价不超过估值、不会输给愿意付更高价的对手，由此给估值分布与最优储备价定上下界。假设不齐时，界比点更诚实。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计流程：先验数据类型——单次出价、入场记录、成交价。IPV 风险中性时直接 GPV 反演（主干课）；加风险曲率时用「不同 \\(n\\)」的变异；有共同乘数嫌疑时反卷积；\\(n\\) 内生时联合估进入。所有路径的下游一致：得到 \\(F\\)（或它的界）后，储备价、合谋、准入的反事实在均衡上重解。<a href="/econ/collusion-cartel">合谋</a>不是废物数据：轮流压价与让标模式在策略上可检验，硬当竞争反演会把合谋报价读成低估值。</p>',11)),(r(),t(A,null,{default:a(()=>[i(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BID%5B%22%E5%87%BA%E4%BB%B7%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20CHK%7B%22%E5%89%8D%E6%8F%90%E6%A3%80%E6%9F%A5%22%7D%0A%20%20CHK%20--%3E%7C%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%7C%20CURV%5B%22n%20%E5%8F%98%E5%BC%82%E8%AF%86%E5%88%AB%E6%9B%B2%E7%8E%87%22%5D%0A%20%20CHK%20--%3E%7C%E6%8B%8D%E5%8D%96%E5%B1%82%E5%BC%82%E8%B4%A8%7C%20DECONV%5B%22%E5%8F%8D%E5%8D%B7%E7%A7%AF%E6%8B%86%E5%85%B1%E5%90%8C%E6%88%90%E5%88%86%22%5D%0A%20%20CHK%20--%3E%7Cn%20%E5%86%85%E7%94%9F%7C%20ENTRY%5B%22%E8%81%94%E5%90%88%E4%BC%B0%E8%BF%9B%E5%85%A5%E6%88%90%E6%9C%AC%22%5D%0A%20%20CHK%20--%3E%7C%E5%85%B1%E5%90%8C%E4%BB%B7%E5%80%BC%7C%20CV%5B%22%E6%94%B9%E4%BF%A1%E6%81%AF%E7%BB%93%E6%9E%84%2C%20%E5%B8%B8%E5%8F%AA%E5%AE%9A%E7%95%8C%22%5D%0A%20%20CURV%20--%3E%20F%5B%22%E4%BC%B0%E5%80%BC%E5%88%86%E5%B8%83%E6%88%96%E7%95%8C%22%5D%0A%20%20DECONV%20--%3E%20F%0A%20%20ENTRY%20--%3E%20F%0A%20%20F%20--%3E%20RF%5B%22%E5%82%A8%E5%A4%87%E4%BB%B7%E4%B8%8E%E5%90%88%E8%B0%8B%E7%9A%84%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=n("p",null,[E("机制还是「策略与分布的耦合」。\\(g\\) 在反演公式的分母：出价在边界堆积或双峰，多半不是估值如此，而是 \\(n\\) 混了样本或策略在边界拐弯。人数变异是最贵的识别资产——\\(n\\) 变，策略的整条曲线按公式预测地动；动得对，IPV 与风险中性才立得住，动不对，先怀疑信息结构与进入。这与"),n("a",{href:"/econ/se-production-deep"},"上一课"),E("的退出同构：参与本身是选择，反演前先把选择层钉住。")],-1)),(r(),t(A,null,{default:a(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20N1%5B%22n%3D3%20%E5%9C%BA%E6%AC%A1%E7%9A%84%E5%87%BA%E4%BB%B7%E5%88%86%E5%B8%83%22%5D%20--%3E%20CMP%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E6%A0%87%E7%9A%84%2C%20%E4%BA%BA%E6%95%B0%E4%B8%8D%E5%90%8C%22%5D%0A%20%20N2%5B%22n%3D5%20%E5%9C%BA%E6%AC%A1%E7%9A%84%E5%87%BA%E4%BB%B7%E5%88%86%E5%B8%83%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%20Q%7B%22%E5%87%BA%E4%BB%B7%E9%9A%8F%20n%20%E6%8C%89%E5%85%AC%E5%BC%8F%E9%A2%84%E6%B5%8B%E7%A7%BB%E5%8A%A8%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20IPV%5B%22%E6%94%AF%E6%8C%81%20IPV%20%E4%B8%8E%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E5%81%87%E8%AE%BE%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20SUS%5B%22%E6%80%80%E7%96%91%E4%BF%A1%E6%81%AF%E7%BB%93%E6%9E%84%E6%88%96%E8%BF%9B%E5%85%A5%E5%86%85%E7%94%9F%22%5D%0A%20%20SUS%20--%3E%20FIX%5B%22%E5%85%88%E4%BF%AE%E6%A8%A1%E5%9E%8B%2C%20%E5%86%8D%E8%B0%88%E5%8F%8D%E6%BC%94%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">数字实例：同样观察到 0.80 元的出价，若出价者风险中性，反演出估值约 0.85；若他因怕输而把出价抬高了一成，真估值可能只有 0.77。风险曲率不确定时，同一份出价分布能倒推出两套方向相反的估值——这就是「估出的是策略的影子」的具体含义。</span></p><p>部分识别的逻辑与主干<a href="/econ/iv-weak-instruments">弱工具</a>课的诚实原则同源：假设供给不足时，报告「数据排除掉什么」比硬给点估计更可信。界可以窄到足以否掉某个储备价方案，这已经够用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推<a href="/econ/revenue-equivalence">收入等价</a>，也不给采购市场的数字。荷式与英式的按钮模型差异不在本课调和。石油租约的共同价值结构只指路<a href="/econ/winner-curse">赢家诅咒</a>课，不展开估。秘密储备、再转售与事后谈判都改反演，遇到要先改模型再估。</p><p><span class="marginnote">常见误区：初学者容易把出价分布的双峰当成「人群天然有两类估值」。更常见的真相是样本里混了不同人数 \\(n\\) 的场次，或出价在储备价边界堆积。先查数据是怎么构造的，再谈异质性。</span></p><p>后课默认：拍卖反演前先过四道前提检查，过了才用主干公式；过不了就走定界。下一课换估计原则：目标函数不光滑、不动点嵌套时，贝叶斯与模拟估计进场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险厌恶、不可观测异质、内生参与、共同价值，逐一改变反演公式。</li><li>\\(n\\) 的跨场变异同时检验 IPV 并识别风险曲率。</li><li>合谋报价不能当竞争策略反演；假设不足时部分识别优于硬点估。</li><li>反事实储备价在修好的 \\(F\\)（或界）上重解。</li><li>出处：Guerre, Perrigne and Vuong, <em>Econometrica</em> 2000 与 2009；Haile and Tamer, <em>JPE</em> 2003；Athey and Haile, <em>Econometrica</em> 2002；Krasnokutskaya, <em>REStud</em> 2011。</li></ul>',8))])}const P=l(p,[["render",c]]);export{f as __pageData,P as default};
